#include <bits/stdc++.h>
using namespace std;

struct Fenwick {
    int n;
    vector<long long> tree;

    Fenwick(int n) : n(n), tree(n + 1, 0) {}

    void add(int index, long long value) {
        for (; index <= n; index += index & -index)
            tree[index] += value;
    }

    long long sum(int index) const {
        long long result = 0;
        for (; index > 0; index -= index & -index)
            result += tree[index];
        return result;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, Q;
    cin >> N >> Q;

    Fenwick fenwick(N);
    vector<long long> people(N + 1);

    for (int i = 1; i <= N; ++i) {
        cin >> people[i];
        fenwick.add(i, people[i]);
    }

    while (Q--) {
        int type, K;
        cin >> type >> K;

        if (type == 0) {
            long long P;
            cin >> P;
            fenwick.add(K, P - people[K]);
            people[K] = P;
        } else {
            cout << fenwick.sum(K) << '\n';
        }
    }

    return 0;
}
